C = "Accounting & finance"
SPECS = [
 dict(type="G", slug="invoice-pdf-email-to-sheet-ai", category=C, name="Supplier invoice emails to sheet (vendor, amount, due date, AI extraction)",
  summary="Reads invoice emails, extracts vendor, invoice number, amount and due date, and adds a row to your payables sheet.",
  tab="Payables", query="in:inbox (invoice OR bill) -from:me",
  prompt="Extract invoice details from this email text. is_invoice, vendor, invoice_number, amount (number), currency, due_date (YYYY-MM-DD or empty). Leave unknowns empty, never guess.",
  schema={"is_invoice":True,"vendor":"Acme Supplies","invoice_number":"INV-1042","amount":420.5,"currency":"USD","due_date":"2026-12-01"},
  notes="Attachments (PDF) are not read by this version: it works from the email text. For PDF-only invoices add an extract-from-file step."),
 dict(type="S", slug="overdue-invoice-chaser", category=C, name="Overdue invoice chaser (polite reminder emails from a sheet)",
  summary="Each morning finds unpaid invoices past their due date and emails the client a polite reminder, then marks the row.",
  tab="Invoices", cols=["invoice_no","client_name","email","amount","due_date","status","last_reminder_at"], when="daily 9",
  filter="String(r.status).toLowerCase() !== 'paid' && daysUntil(r.due_date) !== null && daysUntil(r.due_date) < -3 && (!has(r.last_reminder_at) || daysSince(r.last_reminder_at) > 7)",
  mail=dict(to="{email}", subject="Reminder: invoice {invoice_no}", body="Hi {client_name},\n\nA friendly reminder that invoice {invoice_no} for {amount} was due on {due_date}. If you have already paid, thank you and please ignore this.\n\nKind regards,\n{cfg.sender_name}\n{cfg.business_name}"),
  mark=("last_reminder_at","new Date().toISOString().slice(0, 10)")),
 dict(type="I", slug="stripe-payments-to-sheet", category=C, name="Stripe payments to Google Sheet ledger with thank-you email",
  summary="Logs every successful Stripe payment in a sheet and optionally emails a thank-you. A simple ledger without exporting CSVs.",
  fields=["id","customer_email","amount","currency","status"], tab="Payments", source_note="In Stripe go to Developers > Webhooks, add this **Webhook** URL and send the `payment_intent.succeeded` event. Amounts from Stripe are in cents.",
  notify=dict(via="gmail", subject="Payment received: {amount} {currency}", text="Stripe payment {id} from {customer_email}: {amount} (in cents) {currency}. Status {status}.")),
 dict(type="I", slug="stripe-failed-payment-recovery", category=C, name="Stripe failed-payment recovery email",
  summary="When a Stripe payment fails, emails the customer a friendly note with a link to update their card, and alerts you.",
  fields=["id","customer_email","amount","currency","failure_message"], tab="Failed payments", source_note="In Stripe add this **Webhook** URL and send the `invoice.payment_failed` or `payment_intent.payment_failed` event.", cfg=dict(billing_link="https://billing.stripe.com/p/login/your-link"),
  reply=dict(to="customer_email", subject="Your payment did not go through", body="Hi,\n\nWe could not process your latest payment ({failure_message}). You can update your card here:\n\n{cfg.billing_link}\n\nIf you need help just reply to this email.\n\n{cfg.sender_name}"),
  notify=dict(via="gmail", subject="Failed payment from {customer_email}", text="Payment {id} failed: {failure_message}. The customer has been emailed a billing link.")),
 dict(type="D", slug="weekly-cash-flow-snapshot", category=C, name="Weekly cash-flow snapshot email from a sheet",
  summary="Every Monday reads your income and expense sheet and emails a plain-English snapshot of money in, money out and what is due soon.",
  tab="Cash", cols=["date","type","description","amount","due_date"], when="weekly 1 7",
  prompt="You are a friendly bookkeeper. From these rows (type is income or expense), give money in, money out and the net for the last 7 days, list anything due in the next 14 days, and flag one thing to watch."),
 dict(type="I", slug="expense-approval-request-slack", category=C, name="Expense request log with approval alert in Slack",
  summary="Staff submit an expense request in a form. It is logged and posted to Slack so a manager can approve quickly.",
  fields=["name","email","amount","reason","receipt_link"], tab="Expense requests", trigger="form", form_title="Expense request",
  notify=dict(via="slack", text="Expense request from {name}: {amount} for {reason}. Receipt: {receipt_link}. Reply in the thread to approve.")),
 dict(type="E", slug="bank-transaction-categoriser-ai", category=C, name="Bank transaction categoriser (AI) for a sheet",
  summary="Paste your bank export into a sheet and the AI adds a category for each row, so tax time is easier. Always review the results.",
  tab="Transactions", cols=["date","description","amount"], need=["description"],
  prompt="Categorise this bank transaction for a small business: {description} (amount {amount}). Choose one: software, travel, meals, supplies, utilities, rent, payroll, marketing, fees, income, other. Return a short reason.",
  schema={"category":"software","reason":"Monthly SaaS subscription"}),
 dict(type="S", slug="subscription-renewal-reminder", category=C, name="Subscription and domain renewal reminder",
  summary="Keep a list of your subscriptions, domains and licences. Get an email 14 days before each renews, so nothing renews by surprise.",
  tab="Renewals", cols=["item","cost","renewal_date","reminded"], when="daily 8",
  filter="!has(r.reminded) && daysUntil(r.renewal_date) !== null && daysUntil(r.renewal_date) >= 0 && daysUntil(r.renewal_date) <= 14",
  mail=dict(to="{cfg.owner_email}", subject="Renewing soon: {item}", body="{item} renews on {renewal_date} (cost {cost}). Cancel or keep?"),
  mark=("reminded","new Date().toISOString().slice(0, 10)")),
 dict(type="I", slug="payment-received-thank-you-receipt", category=C, name="Payment received thank-you email with receipt details",
  summary="When a payment webhook arrives (Stripe, PayPal, Gumroad, Paddle, Lemon Squeezy) sends a plain thank-you with the details and logs it.",
  fields=["customer_name","customer_email","product","amount","currency"], tab="Sales log", source_note="Point your payment provider's webhook at the **Webhook** URL. Map the field names or rename keys to match.",
  reply=dict(to="customer_email", subject="Thank you for your order: {product}", body="Hi {customer_name},\n\nThank you for your payment of {amount} {currency} for {product}. Keep this email as your receipt.\n\n{cfg.sender_name}\n{cfg.business_name}")),
 dict(type="S", slug="tax-document-collection-reminder", category=C, name="Tax document collection reminder to clients",
  summary="Accountants and bookkeepers: emails each client a checklist reminder until their documents are marked received.",
  tab="Client documents", cols=["client_name","email","missing_documents","received","last_reminder"], when="weekly 1 9",
  filter="!has(r.received) && (!has(r.last_reminder) || daysSince(r.last_reminder) >= 6)",
  mail=dict(to="{email}", subject="Documents we still need, {client_name}", body="Hi {client_name},\n\nTo finish your return we still need: {missing_documents}.\n\nYou can reply to this email with the files attached.\n\n{cfg.sender_name}"),
  mark=("last_reminder","new Date().toISOString().slice(0, 10)")),
 dict(type="I", slug="purchase-order-approval-log", category=C, name="Purchase order request log with Slack approval ping",
  summary="Team members request a purchase through a form. The request is logged and posted to Slack for the approver.",
  fields=["name","email","item","cost","supplier","reason"], tab="Purchase orders", trigger="form", form_title="Purchase request",
  notify=dict(via="slack", text="Purchase request from {name}: {item} ({cost}) from {supplier}. Reason: {reason}")),
 dict(type="D", slug="monthly-profit-and-loss-summary", category=C, name="Monthly profit and loss summary in plain English",
  summary="On the 1st of each month emails a plain-English P&L summary from your income and expense sheet.",
  tab="Ledger", cols=["date","type","category","amount"], when="daily 7", filter="new Date().getDate() === 1",
  prompt="You are a friendly accountant. From these income and expense rows give total income, total expenses, profit, the biggest expense category, and one practical suggestion. Plain English, no jargon."),
 dict(type="S", slug="client-invoice-due-soon-reminder", category=C, name="Invoice due soon reminder (before it is late)",
  summary="Emails your client a polite heads-up 3 days before an invoice is due.",
  tab="Invoices", cols=["invoice_no","client_name","email","amount","due_date","status","heads_up_sent"], when="daily 9",
  filter="String(r.status).toLowerCase() !== 'paid' && !has(r.heads_up_sent) && daysUntil(r.due_date) !== null && daysUntil(r.due_date) >= 0 && daysUntil(r.due_date) <= 3",
  mail=dict(to="{email}", subject="Invoice {invoice_no} is due on {due_date}", body="Hi {client_name},\n\nJust a heads-up that invoice {invoice_no} for {amount} is due on {due_date}. Thank you!\n\n{cfg.sender_name}"),
  mark=("heads_up_sent","new Date().toISOString().slice(0, 10)")),
]
